/** EH001 siman 004 — editorial redo: pitchei-teshuva, beit-meir, chokhmat-shlomo, rabbi-akiva-eiger */
import { patchFile } from "./_patch-siman-utils.mjs";

const log = [];

function p(rel, slug, T) {
  const n = patchFile(rel, slug, T);
  log.push({ file: rel, blocks: n });
  return n;
}

// ── pitchei-teshuva (37 blocks) ─────────────────────────────────────────────
p("siman_004/pitchei-teshuva/part-001.txt", "pitchei-teshuva", {
  "1#_": `The child is fit. See Ya'arot Devash part 1 derush 17 what he wrote there; and at the start of that hashkafah I wondered greatly why he said that per the view "the child is fit" the child is a gentile — and therefore needed to base his derush only on the view "the child is mamzer" which is not the halakhah, for we rule the child is fit; and truly from all posekim it appears the child is fit and a full Israelite. True Tosafot ruled so in chapter Ten Yuchasin siman 142 — but in Tosafot there Yevamot 75b s.v. veR' Yishmael there is no necessity for this as Maharsha wrote there; and Rashi's words contradict each other on this — see there; and see further Maharsha Yevamot 16b s.v. amorai — examine. Even if one does not answer the derush, this was unnecessary for his derush; rather more correct his derush aliba dihilcheta that the child is fit and also Israelite. I further saw in Shaarei Melekh part 15 laws of forbidden relations halakhah 3 the rabbi expanded greatly on this law and resolved Rashi's contradiction that Maharsha challenged — that Rashi always holds the child is Israelite; what he wrote in chapter HaOmer 68 "the child is fit" by conversion is not so — rather per his view there wherever we cast after Israelite the child is mamzer, etc.; but Tosafot contradict themselves and he expanded further; at end he brought great proof he is full Israelite from sugya Bekhorot 47 (and YD siman 305 s.k. 18) — clear there he is liable for redemption; if he needed conversion why liable for redemption — "your sons" is written; rather certainly fully fit and like full Israelite — see there. I also found in responsum Chemdat Shlomo siman 2–3 great pilpul on this law; Melisa's view that conversion was needed per Rashi's plain language Kiddushin 68b s.v. leima ksavar Ravina — and what Maharsha wondered that Rashi contradicts what he wrote 76b s.v. uferakhinan — he z"l wrote to resolve well and distinguish between born from gentile and born from slave who has no life; nevertheless forbidden in mamzeret for his conversion differs from ordinary converts; proof from Bekhorot 47 (that Shaarei Melekh cited); reason per Yevamot 62 only in their gentility do gentiles have lineage, but in their conversion no lineage needed — therefore conversion needed because as long as not converted still attributed after father; when converted no longer lineage and we cast after mother and he is like full Israelite, his law like Israelite bekhor liable for redemption and forbidden in mamzeret from Torah reason. The gaon Baal HaMaor z"l expanded to dispute him and wrote that the above Rashi is no proof per the conclusion, and Tosafot chapter HaChalitz (Yevamot 47) proves the opposite that conversion is not needed; also proved from Rif and Rambam who ruled gentile and slave who cohabited with daughter — she is not damaged for kehunah; if conversion were needed she would certainly be damaged for kehunah; likewise plain from RaaM parashat Emor and Ramban and French sages he cited there; likewise clear from later Acharonim Beit Shmuel siman 4, Taz, and Shakh YD siman 268 s.k. 10 that if so the halakhah is no conversion needed — see there. Also in responsum Noda BiYehudah tinyana siman 150 plain he adopts no conversion needed and in congregation of Israel he is considered for all matters of sanctity — see there; likewise appears view of gaon Tiferet Moshe YD siman 267 whom I brought in Pitchei Teshuva there s.k. 11 from permitting circumcision on Shabbat — see there; likewise clear in responsum Brit Avraham siman 2 letter 2 and siman 6 letter 6 what he wrote on this — see there.`,

  "2#_": `But damaged [for kehunah]. See responsum Mishkanot Yaakov siman 2.`,

  "3#_": `For kehunah. See Baer Heitev what he wrote nearby bedi'eved we do not remove; see Ahavat Geram letter 10; and see Magen Avraham part 17 laws of forbidden relations end halakhah 7 who cited Maharshal in part 15 halakhah 3: Ramban raised in safek and wrote if she married we do not remove her and child is safek chalal — Maharshal wondered for per one who says child damaged it is Torah law from widow; since rabbi was in safek what halakhah — go stringently like safek divorcee or safek zona that Rambam ruled remove with get; Maharshal wrote plain safek deoraita; answered Ramban holds rabbinically and a fortiori not precise — left tzarich iyun; see Yeshuot Malko chapter HaChalitz; see Shaarei Melekh part 15 halakhah 3 resolving per Maharival part 4 siman 19 — dispute whether forbidden to husband or permitted — follow stringent or lenient since we compel divorce lest coerced get, etc. — see there; can say Ramban adopts Maharival's latter language — only safek divorcee with factual near-relative we remove by force; here safek halakhah no forced removal lest coerced get — rabbi z"l distinguished "do not remove from him" not "he shall not remove" — only by force; see there; see responsum Brit Avraham siman 1–9 and Nachalat Yehoshua siman 11.`,

  "4#_": `Even for kehunah. See Baer Heitev s.k. 5; see Yad HaChazakah on laws of safek deoraita siman 1 seif 4 who challenged Beit Shmuel; also Beit Yosef's difficulty is nothing for no a fortiori in this formulation since she is the giver — gentile and slave kiddushin do not take effect therefore child not damaged; proof: one who holds gentile and slave who cohabited — child fit even if Israelite cohabited with another's wife child mamzer — there is also reason conversely since regarding gentile kiddushin do not take effect preferable regarding child, etc. — see there.`,

  "5#_": `She is permitted. See Baer Heitev; and see responsum Brit Avraham siman 6 letter 10 what he wrote on this.`,

  "6#_": `And Moabite and Ammonite. See She'elat Yaavetz part 1 siman 46 what he wrote on this.`,

  "7#_": `For all who separate. See Shaarei Melekh part 15 halakhah 21 who wrote therefore needed reason of all who separate for permitting congregation even rabbinically; but from Torah without this permitted — Ammonite certainly may not enter; Ammonite safek may enter as we say regarding mamzer — see there.`,

  "8#_": `In his prohibition he stands. See Baer Heitev in name Mordekhai; and see Birkei Yosef who expanded on this.`,

  "9#_": `Her husband abroad. See responsum Brit Avraham siman 86 letter 17 what he wrote on this.`,

  "10#_": `Child mamzer. See what I wrote below siman 158 s.k. 3.`,

  "11#_": `More than twelve months. Birkei Yosef wrote: if she waited more than three days we have no concern lest she did not conceive until the third day — Gan HaMelekh siman 128; but Rabbi Mahari Za'avi carved and hewed from Rambam's and Maran's language that we do not count twelve months except from day of separation — see there.`,

  "12#_": `For we say she waited — Baer Heitev; and see Birkei Yosef letter 7 who brought from Maharshal in Yesh Nohalin chapter HaAreil siman 29 extensive analysis to establish halakhah like Rabbah Tosefta, and also brought in name of Maharil — see there (see responsum Rabbi Akiva Eiger siman 99 who copied Maharil's language there and what Kenesset HaGedolah wondered on him — he z"l wrote to explain his words and remove Kenesset HaGedolah's wonder). Rabbi Birkei Yosef letter 8 further wrote what Gan HaMelekh siman 130 wrote on woman whose husband went abroad and she gave birth immediately after his departure and after several months (seven or nine) gave birth again — we attribute to say from the husband and validate him; for though woman does not conceive and conceive again, minority exists who conceive; second fetus one cannot rely on; for all views they do not return and conceive — fetus exists and no minority here; therefore child mamzer; also Yad Aharon wondered on this — see there. Letter 9 there wrote: however woman who immersed after Passover and afterward husband went abroad and she gave birth on Yom Kippur and again on Shabbat HaGadol — hastily it appears room to validate child — attribute that after Passover when she immersed she conceived twins and one born at seven months and second she waited until twelve months; proof we say she waited in such case from sugya Niddah 27; see Tosafot s.v. ella; see Rashba and Ran in Chiddushei Niddah 25 — matter needs resolution — see there (see responsum Chatam Sofer siman 5); see responsum Noda BiYehudah tinyana siman 80 on woman who bore twins at nine full months whose husband cohabited and traveled and at nine months bore twins — therefore husband suspects adultery because he found in a derush that twins cannot be conceived from one act; he wrote: this husband bears his sin and suspects the fit — the preacher's words are vanity and against many Gemara places; rather opposite — impossible twins from two acts that both are viable — see there.`,

  "13#_": `And specifically when they did not see him come, etc. This law is from responsum Maimonides to laws of marriage siman 25 who wrote on his case: in our case if there were witnesses of seclusion it appears all sides equal she is forbidden to her husband; for since witnesses saw ugly matter and she gave birth likewise at end of twelve months in this — certainly Rabbah Tosefta would not validate; for since there are witnesses of seclusion we do not say she waited — see there. There the question was not about the child for the child was not in the world and he need not rule on him — only on the woman if permitted to her husband; but since he wrote in this certainly Rabbah would not validate, etc. — from this clear the law Rama wrote here regarding child we are concerned for him. So too from Rama's words here regarding child we are concerned — we do not say she waited in such case — from this clear Maimonides' law regarding woman forbidden to husband (however one can reject this is not so clear regarding woman there is safek to permit lest she waited and conceived from husband; if from strange man still perhaps by force — unlike child no difference whether willingly or by force — see responsum Noda BiYehudah tinyana siman 19); see below nearby s.k. 14 and siman 11 s.k. 8–11.`,

  "14#_": `Ugly matter. See responsum Rabbi Akiva Eiger siman 99 who wrote: since Rama stam and did not explain what is called seclusion and its boundary — implies he relied on seclusion in siman 11; so for examiner in Maimonides' responsum the matter is clear that any seclusion not sufficient for questioning is not sufficient even when joined with her giving birth at eight months. From Torah reason it appears clear too: in secluded path of prohibition and she gave birth at eight months — not forbidden; for for seclusion alone she is not forbidden for questioning, etc.; however from Beit Shmuel s.k. 18 language that reason in ugly matter she is forbidden when giving birth at eight months — we do not say she waited only when she has presumption of fitness — implies his intent: since she acted improperly her presumption of fitness was impaired; in my view cannot say so — see there. He further wrote: what implies from Rama's words here that all seclusion mentioned siman 11 forbids when giving birth at eight months — even seclusion of exiting from dark place — one can question; for Mara dehai shmaatsa is Maharam in Maimonides' responsum and he holds seclusion of dark place is not in category of seclusion (see Rosh chapter 2 Yevamot); if so we should be lenient in dark-place seclusion with birth at eight months. Though who will raise head to be lenient against Rama z"l — nevertheless the strap was permitted to judge where possible it is not in category of dark place — see there; siman 100 Beit Meir challenged him and siman 101 Ra'ak z"l answered and concludes: but since your honor questions in any seclusion in the world even in prohibited path with birth at eight months one can say forbidden — Heaven forbid for me to be lenient against him — see there.`,

  "15#_": `We do not say she waited. See responsum Ra'ak Eiger there end siman 39 who wrote: also what your honor wrote that after husband left she became niddah — in such case there is room to forbid when giving birth at eight months, etc.; in my view plain in mishnah chapter 1 Niddah that pregnant woman only when fetus recognized is blood removed not before; likewise Kenesset HaGedolah in name Radbaz part 1 siman 12: if husband claims not his son that when he left she was in niddah and admits he cohabited before her period — if between last cohabitation husband admits and birth of child no more than eight months child fit — see there (likewise there siman 128 what she became niddah no evidence she is not pregnant; he added even though we see our women immediately when pregnant blood removed and natures changed — nevertheless see YD siman 189 and 190 where pregnant when fetus recognized mentioned and no hint in Acharonim that for us even without recognition — see there; see further responsum Noda BiYehudah siman 69 brought briefly below siman 156 s.k. 5; see Pitchei Teshuva YD siman 194 s.k. 3). He further wrote what responsum Yad Eliyahu siman 84: only when giving birth at eight months permitted but at nine or eleven months forbidden for she does not wait except nine or twelve months. In my view no need to heed his words for Chelkat Mechokek and Beit Shmuel plainly validate at eleven months and likewise precise Rambam's language and clear from Maharil brought in Kenesset HaGedolah — see there.`,

  "26#_": `And forbidden in mamzeret. See Chelkat Mechokek and Beit Shmuel; and see Shaarei Melekh part 15 laws of forbidden relations halakhah 9 what he wrote at length on this.`,
});

p("siman_004/pitchei-teshuva/part-001.txt", "pitchei-teshuva", {
  "16#_": `And we are concerned for him. See responsum Ra'ak Eiger siman 100 on responsum Beit Meir who sided to permit the child in the case asked about (brought below siman 11 s.k. 11 — she gave birth near eleven months and testimony on seclusion matters but not actual witnesses of seclusion) and wrote: though from side of no actual witnesses of seclusion difficult to permit — possible since Rama did not write in siman 11 what is called seclusion only stam — but if they saw ugly matter perhaps Rama means any seclusion in world's eyes. Nevertheless in substance of law no worse than very promiscuous woman — clear there (below seif 15) we are concerned even for sons and nevertheless she is trusted, etc.; likewise here if mother testifies no man cohabited except husband and certainly from husband — trusted to validate him. What Maharam wrote in Maimonides' responsum "certainly Rabbah would not validate" means per Gemara stam slave acted and validated — implies without examining mother and even if died without examination — Rabbah would not validate stam but when standing yes; in Maharam's case child not in world to stay on him and he did not descend to explain. Again rejected this permission (for Taz challenged there since not trusted regarding herself how much more child, etc.; but in Beit Meir he wrote to resolve and distinguish: regarding herself it is like definite and definite but regarding child even very promiscuous applicable "she knows this child from husband" — therefore in our case seclusion and birth at eight months not like that not trusted regarding child as not helping to validate herself) but wrote still room to permit per Mahari Weil brought in Beit Shmuel s.k. 43 — from fetus safek for even with gentile from safek does not emerge; perhaps from husband as Rama's language precise "we are concerned for him"; if say from prostitution perhaps from idol-worshipper child fit, etc.; he expanded and wrote at end from Maharam's words no proof for child not in his case; wrote Rabbah would not validate stam because she waited alone and Rama z"l dragged after them to write stam "we are concerned"; possible difference city all Israelites or gentile foot not common in Israel street and Israel foot not in gentile street. What wrote in our case no actual witnesses of seclusion, etc. — see there (at end wrote: further safek if possible to rule congregation disqualification today per witnesses on her because like not in his presence and congregation disqualification certainly capital cases money — see CM siman 38 and responsum Mahari"t part 2 siman 36 and responsum Rama siman 12 and responsum Pnei Aryeh siman 109 — see there). There siman 101 in responsum Ra'ak z"l he agreed to all his words that law of permitting this child (though somewhat leaned in reasoning) and he strengthens first permission from mother's examination helping validate child (what Beit Meir rejected not necessary — can say not helping regarding herself not because definite and definite but presumption of fitness removed — for child not needing presumption as clear from Rambam and Shulchan Aruch below siman 129 — can say trusted); especially since also safek perhaps from husband perhaps from gentile — now in all towns majority are not plain Jews easier to permit from definite and safek, etc.; especially our case no actual seclusion only passing per path — I thought to say Maharam admits fit only Ra'ak questions and I do not wish to be lenient against him (as above s.k. 14) — at least support to be lenient combining permissions — see there. Siman 102 Beit Meir returned and answered and he questions permission alone and wrote: nevertheless I stand on my watch to validate child and even if afterward you saw in responsum Orim Gedolim he brought in name Maharam Minz that even in majority gentiles before her we attribute to Israel minority and not gentile — one sage challenged and author wants to agree with Maharam — expands in proofs — all his proofs fall per what I explained law of fiancée discusses city all Israelites or no room to doubt gentile; but from Torah to invent such reasoning to attribute to Israelites not promiscuous (see below siman 29 s.k. 39, etc. — see there). There siman 103 responsum Ra'ak z"l again — expanded further and wrote at end: however what appears from your honor's words to be lenient in safek they are not Jews except city all Israelites — implies even in majority Israelites safek; this in my view doubtful for law since Rashba and Ritva even where safek if she goes to him called majority — can say not safek; at least if majority gentiles my opinion concludes practically to validate child in congregation — see there; see further siman 106 what he pilpul'd with Rabbi Ze'ev Eiger; concludes: for law at least minor seclusion and through her definite and city majority gentiles like our case — room to validate child if rabbis agree with me — see there.`,

  "17#_": `The months cause. See Beit Meir here and responsum at end of his book siman 10 who poured battery of difficulties on Maharam Minz and Rama z"l; brought there also Mahari"t part 2 siman 15 decided not like Mahari Minz; also printed responsum gaon Rabbi David Tevel z"l of Lissa and gaon Maharam Barbi z"l who answered to strengthen Rama's ruling and he z"l returned and questioned their words and concludes this matter greatly doubtful in practice — see there; see responsum Noda BiYehudah siman 22 (brought below siman 13 s.k. 18) plain he rules like Mahari Minz and Rama z"l — see there. (Also responsum Chatam Sofer siman 6 discusses exactly such case — woman married 15 Sivan and cohabited again end Sivan and bore daughter start Kislev and people gossip perhaps cohabited before marriage but both admit they did not touch before and therefore cohabited after and husband claims mistake and wants to divorce — asked whether we say in this months cause per Rama's ruling; he expanded and concludes: emerges from all above that not only if cohabited again end Sivan and bore start Kislev we attribute to fitness but even only first cohabitation in Sivan — nevertheless well wrote in responsum Noda BiYehudah siman 22 brought siman 13 there that nowadays cannot rely on this reasoning (woman does not conceive from one act) and further minority exists and cannot say therefore two majorities to be stringent — majority women do not conceive from one act and majority women who bear at seven do not bear at five months — nevertheless presumption of fitness and righteousness from majority — majority Israelites are fit and presumption here found presumption of body that now she cohabited and worthy are these geonim to rely on them — woman and daughter both fit; nevertheless if such matter of Torah prohibition immediately before us I would require further waiting and moderation before final ruling — see there). There siman 7 regarding kohen who betrothed maiden from afar and she came to his place and after time married and after two months bore viable son who lived thirty days and both admit child from him for he said cohabited 28 Nisan and she bore thirtieth of Kislev which is first of Tevet and there are challengers saying they only came together 4 Iyar and per their words he is eight months every way even if months cause and bear truncated and cannot live thirty unless she waited and we do not say she waited except to uphold woman's fitness lest say she prostituted — see Rivash siman 246 and Maharik siman 103; but here we say she made herself available before betrothed and since she said from him and per my view she lies — as not examined and difficult to permit kohen for though if married not remove even majority promiscuous nevertheless needs say cohabited with fit and here said nothing in speech from him presumed — see that responsum siman 29 brought briefly below siman 6 s.k. 20. All this per challengers but they only challenge not full denial for he is trusted on himself to say cohabited end Nisan which is nine months per one who says months cause (for per one who says not months cause even bearing truncated nevertheless here need complete three missing months and then not enter ninth month even one day); though very difficult for me to enter this permission for kohen for Mahari"t part 2 siman 15 and Etz Avraham siman 4 and Beit Meir in his responsa siman 11 all question Mahari Minz's ruling — his teacher too disputants and lenient; there Beit Meir Tevel and Maharam Barbi disputed him and wrote he made practical halakhah and who will compel against these geonim and Rama's ruling — this language very difficult in my view though truly many geonim lenient say months cause even bearing at nine and as Beit Shmuel here in name Tosafot and Agudah and siman 156 s.k. 5 in name Ramban — nevertheless Rama's ruling certainly not so — only bearing at seven we say months cause but bearing at nine even truncated from changed natures nevertheless we do not say months cause as Rama z"l explicitly siman 156 s.k. 4 in hagahah; however months of pregnancy each thirty days, etc.; reason of distinction clear in Bach there letter 11 — doubtful); he expanded further and at end wrote general rule I conclude as Rivash above concluded: lenient has pillar to rely and stringent examine — see there; see responsum Chemdat Shlomo siman 79 what he wrote on this.`,

  "18#_": `And even if she miscarried in Tishrei, etc. See responsum Noda BiYehudah tinyana siman 19 where he expanded greatly on this ruling — see there at length; see responsum Brit Avraham siman 78 letter 8 who also z"l wondered on Rama here — why permit her in such case against majority viable births and majority nine-month births, etc.; he is satisfied to resolve because against those majorities there is presumption adulterous woman does not conceive (above siman 13 s.k. 6) and presumed from husband since not transformed — supports presumption of righteousness; there siman 81 letter 9 wrote again found in Noda BiYehudah Mahadura tinyana siman 19 who challenged thus on Rama (as brought above) and pilpul'd to combine safek force and he z"l wrote on him: even for posekim (below siman 308 s.k. 7 in hagahah) "I was forced" against majority of will — rabbinic — nevertheless do not trust her in miggo of force for Rama did not distinguish here to forbid kohen's wife or such case where we know she was always in place force impossible (see above siman 6 s.k. 11) — but main resolution as I wrote — see there.`,

  "19#_": `That majority of cohabitations. See responsum Chut HaShani siman 18 who wrote we rely on this even for inheritance — see there.`,

  "20#_": `They are chalalim. See Baer Heitev in name Beit Shmuel who wrote: but if her husband Israel — if she prostituted intentionally sons she bears afterward are fit even for kehunah; see responsum Shivat Tzion siman 75 who wrote Beit Shmuel did not see Maharshal's words in Yesh Nohalin Yevamot chapter 4 siman 38 and 55 who wrote explicitly that though we do not rule like R' Chiya and not mamzer rabbinically — nevertheless child disqualified for kehunah; but from Tosafot Yevamot 49b s.v. sotah in what they wrote to reject R' Chiya from chapter "there are permitted" proves Beit Shmuel's view — even for kehunah child not disqualified — see there.`,

  "21#_": `We are concerned even for sons. See Beit Shmuel s.k. 26 what he wrote that sugya Sotah discusses kehunah prohibition; see responsum Noda BiYehudah tinyana siman 2 what he challenged on this and what he answered — see there; also responsum Shivat Tzion siman 75 mentioned from this — see there.`,

  "22#_": `She is trusted. See Taz; and in Beit Meir; and see above siman 14 s.k. 16.`,

  "23#_": `Between married woman. See responsum Bashamayim Rosh siman 5 asked: married woman who left religion and married Ishmaelite and had sons and afterward returned to Judaism — what law of sons when one wanted to say we are concerned perhaps she prostituted with Israelite; he z"l answered: my opinion does not agree that if she was presumed all Israel not presumed; even if compare to that fiancé and fiancée case and even Israelites suspected or apostates go to her house — nevertheless husband guards her and majority cohabitations after husband — that majority R' Gamliel and R' Yehoshua dispute is where she prostituted; but man who returned with wife regularly — one gentile one Israelite — his sons attributed after him — see there. See responsum Chemdat Shlomo siman 1 similar case in practice (in Ishmaelite land) — woman left husband agunah more than forty years, mixed among Ishmaelites, did not practice Judaism though did not convert — no Jewish spark; afterward bore daughter and raised among Ishmaelites — daughter did not know what nation until before death mother told her Jewish and commanded stand in Judaism and she did; constant rumor this daughter known Arab; witnesses say before pregnancy mother prostituted in village several times with one Arab and no Jews regularly there only merchants; also one Jew sometimes — what judgment of daughter if concerned perhaps impregnated from Israelite; though majority fit before her for lineage need two majorities as clear in Gemara and posekim. He answered at length and initially sided per Noda BiYehudah siman 5 (brought below seif 31) — if mother died and need rule only on child — one majority suffices and only for kehunah lineage need two majorities; our case preferable to Noda BiYehudah's for even if mother alive no difference against mother whether prostituted with Arab or Israelite — ultimately forbidden to husband; from other side our case worse than there per what he raised that majority alone does not help except with examining presumption prostitutes lest disqualify — not applicable here; nevertheless his reasoning not forced; truly main words wondrous — from Rambam almost explicit even if mother not examined until death, etc.; even per above our case preferable since never place to judge mother — can say child called separated; nevertheless very difficult if so child from divorcee and chalalah where no judging mother — not in shetuki, etc. (above seif 31 wrote even woman already divorcee has safek forbidden to kohen also as zona — see there; therefore not proof for our case no difference regarding mother); he expanded and concludes per Tosafot Nazir 12 only minority mamzerim called fixed called name disqualified not near minority — room to permit if known born at least in majority Ishmaelites though one majority; per testimony no clear evidence — difficult to be lenient; even Beit Shmuel (siman 6 s.k. 31) where known prostituted with fit — majority helps; in hagahot Gemara wrote even one majority not needed — nevertheless not helping here known prostituted with Arab — can say abandoned worse since presumed to prostitute; can side since main connection only Arabs and changed dress and did not hold Jewish religion — all clear in testimony — Tur's view as Beit Shmuel s.k. 43 and Noda BiYehudah — with Israelite not concerned for Arab and reason change of religions not so close; our case behaved totally Arabite and certainly distant from Israel congregation as testimony did not gather to Israel house — not concerned for Israel; also supports presumption of fitness of Israel and majority Israel not promiscuous — can say even Rambam's view (concerned for Arab) not concerned for Israel; again brought responsum Bashamayim Rosh (as above this s.k.) — clear there this reasoning and wrote seemingly unnecessary his reasoning husband guards and majority cohabitations — only where known suspected and apostates enter her house but where unknown not concerned prostituted with Israelite — likewise our case though majority cohabitations reason not helping except marriage path — this reasoning stronger all Israel not presumed, etc. — concludes this daughter permitted enter congregation; there siman 2 responsum gaon of Lissa z"l agreed and wrote plain and no need inside — our case better than Beit Shmuel siman 3 s.k. 31 Israelis neighborhood separately lest prostituted with Arab — how much more here dwelling among Arabs and majority Israel not promiscuous, etc.; some proof nowhere found son of apostate forbidden congregation lest prostituted with mamzer or gave like concerned for single woman needing two majorities or in her fixed dwelling among Arabs we follow main fixed residence — see there. What further wrote whether needed conversion before — I wrote above s.k. 65 s.k. 1.`,

  "24#_": `Lekhatchilah maidservant. See Baer Heitev in name Shakh that definite mamzer; see Bnei Chayyim what Nissim Yisraeli wrote in name great sage who ruled safek mamzer can purify his seed thus: Jew frees his maidservant on condition she marry fit man — then this safek mamzer can marry that maidservant if he is fit his seed fit and if mamzer maidservant not freed, etc. — see there (likewise Ram"a Mipano in article Chikur Din brought below seif 22 s.k. 25). What Baer Heitev wrote but Radbaz ruled even safek mamzer, etc. — see Birkei Yosef letter 12 who brought responsum Zera Avraham part 4 siman 27 decided like Radbaz safek mamzer permitted with maidservant and hung on Rambam's words; wondered on responsum Pnei Moshe part 3 siman 1 disputing Radbaz; he z"l wondered on him and Radbaz — from Rambam Tur and Maran above seif 17 plain safek mamzer forbidden with maidservant for there half-slave who cohabited with forbidden relative child only safek mamzer (from ruling below siman 44 s.k. 1 if betrothed safek betrothed and Tur in this law child mamzer must mean safek mamzer) and nevertheless child has no remedy and forbidden with maidservant — see there. Also Shaarei Melekh part 15 end halakhah 4 wondered on Radbaz and Zera Avraham — omitted words of Ran Ritva and Rashba beginning chapter Ten Yuchasin — from their words plain shetuki and asufi forbidden with maidservant — see there; in margin Shulchan Aruch of Rabbi Akiva Eiger z"l wrote in name responsum Ramban siman 288 like Radbaz even safek mamzer permitted with maidservant — see there.`,

  "25#_": `Permitted with mamzeret. See Baer Heitev what he wrote: however convert Ammonite who wanted to marry maidservant, etc.; Beit Shmuel s.k. 35 wrote seemingly depends on two answers mentioned earlier (s.k. 31) — for Rambam can say permitted to validate his seed; for R"T, etc.; see responsum Brit Avraham siman 6 in hagahah letter 3 who wrote even for Rambam no proof — can say they permitted only because impossible ever validate seed — mamzer; but Ammonite impossible descendants not born daughter fit as Ammonite not Ammonit and also seed fit — see there; see Shaarei Melekh part 15 end halakhah 4 who wondered on Chelkat Mechokek and Beit Shmuel from Rashba's words in his chiddushim chapter HaAreil (Yevamot 77) who wrote there Egyptian convert permitted marry maidservant and brought Yerushalmi chapter Ten Yuchasin saying in his regard Ammonite given maidservant — clear Rashba's view maidservant prohibition from Torah per R"T as beginning Ten Yuchasin; see Ram"a Mipano article Chikur Din letter 29 who wrote my father David feared perhaps Moabite and even Moabitess and sages said he separated from wife in old age to fulfill "do not let your hand rest in evening" — sought cohabit maidservant and freed on condition — see there; plain convert Ammonite and Moabite permitted with maidservant — see there.`,

  "27#_": `And the other safek. See Baer Heitev; see Shaarei Melekh part 15 halakhah 9 who brought in name Mahari"t Choshen Mishpat siman 1: what Torah permitted safek mamzer entirely permitted from Torah of certainty and not Torah of safek; even to marry mamzeret and Israelite as one — two contradicting — Torah permitted because whatever safek he is like congregation by itself and not called congregation — see there.`,

  "28#_": `And we know that so-and-so. See responsum Shivat Tzion siman 67 who stood on language change between Rambam and Shulchan Aruch — Rambam part 15 halakhah 12 wrote "if she says to so-and-so mamzer I was impregnated," etc. — implies he and she know he is mamzer; from Shulchan Aruch language implies she does not know that so-and-so is mamzer only we know he is mamzer — see there; he wrote correct reason for this.`,

  "29#_": `Even if he admits. See Beit Shmuel s.k. 90 what he wrote; but still not resolved why we are concerned here perhaps she prostituted with another for no disputant here, etc.; see responsum Rabbi Akiva Eiger siman 106 — appears to resolve: possibly truly where witnesses mamzer cohabited with her since she made herself available to world; but here no witnesses only he admits — since anyway concern from Torah because she made herself available — automatically no judging father certainly and in such case not Torah-trusted and not in category yichur and not believed at all that cohabited, etc. — see there. Beit Shmuel further wrote: also appears when known prostituted with fit and here majority cohabitations, etc. — see on this below siman 6 s.k. 17 s.k. 15.`,

  "30#_": `And even if she was secluded, etc., and even one witness, etc. See responsum Chut HaShani siman 19 who expanded greatly explaining Rama's words here.`,

  "31#_": `She was secluded. See Beit Shmuel s.k. 42 who wrote in CM understood, etc. — none; for in such case not concerned, etc.; see responsum Shivat Tzion siman 67 asked ugly case: widow who had sons from husband prostituted to fornicators and said conceived from husband's brother and he admits from him she conceived and afterward went and married where they did not know she was brother's wife — asked whether to hold this son of fornicators definite mamzer per Beit Shmuel siman 4 s.k. 42 or only safek mamzer say perhaps also prostituted with others for in Israel safek widow — brought even with concubine concerned perhaps also with another and likewise Mordekhai chapter 2 Yevamot (Beit Shmuel siman 156 s.k. 1), etc.; he answered at length and raised per majority posekim we drink from — in our case definite mamzer and Nissim Yisraeli and Mordekhai minority against these great posekim; also possible Mordekhai admits, etc. (see siman 156 s.k. 2 s.k. 3); rejected other permission sides questioner wrote and concludes: conclusion of this ruling more opinion inclines to hold this child definite mamzer; even if when grows asks permitted mamzeret or maidservant I would not hasten to permit — nevertheless nowadays maidservant and mamzeret uncommon and nevertheless practical difference for us to hold him definite mamzer — if grows and cohabits Israelite daughter and child safek from him or other — if he himself safek not forbidden congregation only rabbinically — safek of his son rabbinic safek go leniently validate even rabbinically; but if definite mamzer forbidden congregation from Torah — safek of his son forbidden at least rabbinically; further practical difference testimony — if married Israelite daughter and definite mamzer transgressed negative and disqualified testimony from Torah; if only safek mamzer fit testimony — see there; also there even safek mamzer not forbidden congregation only rabbinically — also publicize at circumcision as Beit Din siman 265 s.k. 4 in hagahah unlike questioner who wanted to distinguish — see there.`,

  "32#_": `And forbidden in relatives of that so-and-so. See responsum Noda BiYehudah tinyana siman 40 regarding single woman who conceived in prostitution and bore son and said impregnated from so-and-so Levi and he denied and she was attributing from several youths and now son of fornication ascends to Torah as Levi and also washes for priests; he wrote plain we warn him she is not trusted only to validate in congregation but not to hold him son of that so-and-so; even if admitted cohabited if not admit impregnated from him and she attributes from world and a fortiori completely denied — what one teacher argued deserves to hold him Levi lest otherwise concern permit in so-and-so's relatives — nothing in this for concern also opposite sanctify relatives and permit without get; moreover body of this matter to forbid relatives of so-and-so needs Gemara study — can say what clear we are concerned for her words to forbid relatives of so-and-so is where that so-and-so does not explicitly deny not his son only did not admit to her and discusses he is not here or is here and admits cohabited but says perhaps also prostituted with others; but saying certainly not his son — Torah gave him trustworthiness even with fiancée or wife trusted to say child not from him to permit mamzeret (see below siman 128 s.k. 36 and why not trusted to permit in his relatives — matter needs study (see above s.k. 38)) — at least we warn him not to hold himself Levi — see there.`,

  "33#_": `But he denies her. See Shakh YD siman 305 s.k. 133; and Shaarei Melekh chapter 15 end halakhah 17.`,

  "34#_": `Portion of prohibition. See Baer Heitev what he wrote: and if there are convincing forearms, etc.; seemingly Ran follows Mahari'a brought in Magen Avraham part 3 laws of yibbum halakhah 13 who holds made herself one-sided matter — not applicable where two witnesses contradict his words; unlike Rashba brought there and Rashdam and Shakh brought Baer Heitev below siman 48 s.k. 2 and responsum Noda BiYehudah siman 58 brought for us below siman 42 s.k. 4 — even witnesses contradict his words made herself one-sided plainly forbidden here convincing forearms not stronger than two witnesses — doubtful.`,

  "35#_": `Child safek mamzer. See Beit Shmuel; and Shaarei Melekh chapter 15 halakhah 18.`,

  "36#_": `On fetus that is not from him. See responsum Noda BiYehudah siman 4 who answered regarding one who said of wife fetus not from him only she conceived to fornicators — whether child permitted with mamzeret; he wrote: I saw decided in opinion of questioning rabbis of all posekim except Behag this child definite mamzer permitted with mamzeret; I wonder their question not mentioned husband said fetus is mamzer only said not pregnant from him only conceived to fornicators — this distinction clear in Rambam part 15 halakhah 16 trusted to say this fetus if my son and mamzer he is — definite mamzer; halakhah 19 wrote: if she was pregnant, etc., and father said not my son or husband abroad — in presumption of mamzer, etc., and did not write here definite mamzer — since not testifying she is mamzer only testifying not from him therefore not definite mamzer lest Arab impregnated — clear Beit Shmuel s.k. 52; even Tur's view also this definite mamzer — who will raise head to permit with mamzeret against Rambam where my reason seems — hidden from woman's eyes whether prostituted Israelite or Arab therefore I wonder on you and at least forbidden with mamzeret — see further; see Shaarei Melekh chapter 15 halakhah 15–17 who also stood on contradiction in Rambam's words mentioned and he z"l divides otherwise: halakhah 16 discusses when she claims impregnated from him — there certainly not attribute say perhaps gentile and slave since she claims opposite; halakhah 19 discusses she claims nothing e.g. died, etc. — child safek mamzer concerned perhaps gentile and slave impregnated; per this wrote to wonder on Beit Shmuel seif 52 what wrote Tur disputes Rambam and seems all who did not claim she impregnated from gentile and slave child definite mamzer — wonder this language Tur exactly Rambam's language — perforce say as I wrote there discusses when she claims from him and likewise clear Maran's language in Beit Yosef holds Tur and Rambam same language one matter — see there (per this possible resolve questioning rabbis in Noda BiYehudah responsum — there case woman claimed from husband pregnant therefore ruled child definite mamzer); see following s.k. and below s.k. 39.`,

  "37#_": `Not his son — trusted to disqualify. See responsum Rabbi Akiva Eiger siman 128 asked in case: one challenged wife defiled — found her in act with substance and witnesses on seclusions (in responsum also clear she was then pregnant and also challenged before court on child for some months not in his house and afterward did not approach — see in what time she will give birth) and court ruled divorce her and he divorced and afterward bore son and relied on her apron and sued him in courts to support son and he said in court clarify not his son and was found liable in their law; man remarried other woman and bore sons and first from her died; now son of divorcee about twenty years cries find remedy enter congregation (in responsum clear two witnesses testify he said before them cohabited when returned home only once or twice but in his view far impregnated then). He answered long ruling to permit for three permission sides before us. One: Behag's view trusted say not my son only through bekhor recognition saying on minor he is bekhor. Two: Ri"d's view trusted say not my son only where she does not contradict e.g. died and not examined; when contradicts not trusted. Three: Riaz in She'erit Yosef and likewise Sefer HaMakri'a siman 64 trusted only saying he is his son and mamzer or "not my son" Torah trusted to disqualify; not say not my son and mamzer; as responsum RaaN siman 45; since RaaN stam and did not investigate if one saying not his son is first among other sons especially seems case single woman — saying not his son like saying this is not my bekhor; nevertheless all not through bekhor recognition afterward or like our case no bekhor recognition after for first from second wife died — not trusted; though difficult lean from Rambam and Shulchan Aruch implying trusted say not my son in all matters — nevertheless since questioning rabbi testifies in his city known and published said so in courts to exempt support — if returns say he is son trusted like that in Bava Batra 127b transgressing customs house and our case per two witnesses testifying said before them cohabited when returned once or twice and far impregnated — trusted in this and not category return and tell; also no contradiction in words after per his view not impregnated from once cohabitation — can say for this said in courts not his son judging by calculation and truly errs in imagination and impregnated then. Also even if think from before journey still bore before twelve months and we rule she waited; though in seclusion not lenient in such case (as above seif 14 in hagahah) — can say only to permit herself but regarding child can say trusted (see from this above s.k. 16); what one rabbi questioned since also joined matter she descended immerse after he came home and way of pregnant blood removed — can say blood removal only when fetus recognized; whence immersed for niddah — perhaps saw stain and truly from elsewhere or saw slight reddishness, etc. Further appears even if law in our case if witnesses testify distanced from house time and on return did not approach in manner per calculation birth more than nine months from distancing — do not permit child with witnesses of seclusion — nevertheless not trusted say was so — can say only through clear recognition not his son; in this even per his words possible this his son lest she waited; or say was so leaves us safek if his son — not recognition path. Further appears not judge at all his statement then while pregnant for I wrote in margin Shulchan Aruch CM siman 277 s.k. 3 judge saying this my son or not my son on fetus though bekhor recognition path — nevertheless not trusted for no recognition for fetus — proof Rosh chapter 8 Bava Batra siman 21; if so our case statement while pregnant or automatically witnesses who said cohabited when returned home is superior testimony. Even known these witnesses close to each other — son-in-law gaon Mipano Nissim Yisraeli already ruled permit; though his view not so clear and questioning rabbi also argued helps multiplicity testimony from women testifying cohabited after return — can answer; nevertheless since great support from RaaN above and at least through three permission sides we make safek of law — if so safek on safek of those rabbis and not trusted at all not his son and safek perhaps Arab (see previous s.k.); through safek can rule if marries woman his daughter disqualified for kehunah per Ramban what we say gentile who cohabited — his son damaged means actual son who is chalal to disqualify woman in his cohabitation — automatically his daughter disqualified for kehunah like daughter of chalal; however many posekim rejected main law son damaged from halakhah and for many posekim son not literal only daughter damaged father not chalal and Ramban himself makes safek of law and if married kohen not remove — well rely on three pillars of world for whom not my son in our case generally say not my son and automatically establish son from him and call to Torah father's name; issued with agreement son-in-law gaon KK Presburg ruling to permit — see there (see responsum Chatam Sofer siman 13); see Shaarei Melekh part 15 end halakhah 17 and responsum Shivat Tzion siman 67 on this matter.`,
});

